#include <deque>
#include <iostream>

int main() {
    std::deque<int> d;
    // O(1) operations
    d.push_back(5);
    d.push_front(1);
    d.push_back(10);

    // O(1) random access
    std::cout << "Middle element: " << d[1] << "\n"; 

    // O(1) removal
    d.pop_front();
    d.pop_back();

    // O(N) complexity for middle insertion
    d.insert(d.begin() + 1, 7); 

    for (int x : d) {
        std::cout << x << " ";
    }
}
